from typing import Dict, List, Optional

from pydantic import BaseModel, Field, computed_field

# Built-in scale_metrics produced by the bundled metrics judge prompt. These are
# the only metrics that feed ``bot_quality``: customers can add their own scale
# metrics via the prompt + JSON schema, but those custom metrics are reported
# individually and intentionally excluded from the headline quality number so a
# customer-defined metric cannot silently move it.
DEFAULT_SCALE_METRIC_KEYS = (
    "helpfulness",
    "repair_quality",
    "coherence",
    "tone",
)

# Built-in binary_metrics produced by the bundled metrics judge prompt.
DEFAULT_BINARY_METRIC_KEYS = ("task_completion",)


class CriterionResult(BaseModel):
    """Result of a single LLM-evaluated success criterion."""

    criterion: str = Field(description="The criterion that was evaluated")
    passed: bool = Field(description="Whether the criterion was met")
    reasoning: str = Field(description="LLM reasoning for the verdict")


class ScaleMetricResult(BaseModel):
    """Score (1–5) and reasoning for a graded quality metric."""

    score: int = Field(description="Score on a 1–5 scale (5 = excellent)")
    reasoning: str = Field(description="One-line reasoning for the score")


class BinaryMetricResult(BaseModel):
    """Pass/fail verdict and reasoning for a binary metric."""

    passed: bool = Field(description="True for pass, false for fail")
    reasoning: str = Field(description="One-line reasoning for the verdict")


class CriteriaJudgeCall(BaseModel):
    """Results from the success-criteria judge call (Call 1)."""

    results: List[CriterionResult] = Field(
        default_factory=list,
        description="Results for each success criterion",
    )
    error: Optional[str] = Field(
        default=None,
        description="Error from the criteria judge when it failed independently",
    )


class MetricsJudgeCall(BaseModel):
    """Results from the quality-metrics judge call (Call 2).

    Splits into two metric groups so customers can add metrics by editing
    only the prompt and its JSON schema — the validator/parser handles them
    generically (it enforces shape, not membership):

    * ``scale_metrics`` — graded 1–5 quality dimensions (e.g. helpfulness).
    * ``binary_metrics`` — pass/fail verdicts (e.g. task_completion).
    """

    scale_metrics: Dict[str, ScaleMetricResult] = Field(
        default_factory=dict,
        description="1–5 scored metrics keyed by metric name",
    )
    binary_metrics: Dict[str, BinaryMetricResult] = Field(
        default_factory=dict,
        description="Pass/fail metrics keyed by metric name",
    )
    summary: Optional[str] = Field(
        default=None,
        description="Overall summary from the metrics judge",
    )
    error: Optional[str] = Field(
        default=None,
        description="Error from the metrics judge when it failed independently",
    )


class LlmJudgeResults(BaseModel):
    """Combined results from the LLM judge (criteria + metrics)."""

    criteria: CriteriaJudgeCall = Field(
        default_factory=CriteriaJudgeCall,
        description="Success-criteria judge output (Call 1)",
    )
    metrics: MetricsJudgeCall = Field(
        default_factory=MetricsJudgeCall,
        description="Quality-metrics judge output (Call 2)",
    )

    def scale_metric_scores(self) -> Dict[str, int]:
        """Per-scale-metric scores keyed by metric name."""
        return {k: v.score for k, v in self.metrics.scale_metrics.items()}

    def binary_metric_verdicts(self) -> Dict[str, bool]:
        """Per-binary-metric verdicts keyed by metric name."""
        return {k: v.passed for k, v in self.metrics.binary_metrics.items()}

    @computed_field  # type: ignore[prop-decorator]
    @property
    def bot_quality(self) -> Optional[float]:
        """Mean of the built-in ``scale_metrics`` scores (1–5), to two decimals.

        This is the recommended customer-facing headline for "is my bot
        doing well?". Only the built-in metrics in ``DEFAULT_SCALE_METRIC_KEYS``
        contribute: customer-added scale metrics are reported individually but
        excluded here, so a custom metric cannot silently move the headline.
        Returns ``None`` when none of the built-in scale metrics are present.

        Binary outcome verdicts (e.g. ``task_completion``) are tracked
        separately via ``binary_metric_verdicts`` and intentionally excluded
        here, so outcome failures the bot did not cause (system blockers,
        user pause, voluntary dropoff) do not drag this number down.
        """
        scores = [
            metric.score
            for key, metric in self.metrics.scale_metrics.items()
            if key in DEFAULT_SCALE_METRIC_KEYS
        ]
        if not scores:
            return None
        return round(sum(scores) / len(scores), 2)
